        ctx: StepContext[MLFFWorkflowState, GraficoDeps, PropertyDispatch],
    ) -> PropertyResultCarrier:
        """Compute elasticity tensor."""
        state = ctx.state
        structure, _, outcome = ctx.inputs
        with logfire.attach_context(outcome.trace_carrier):
            with logfire.span(
                "MLFFElasticity {formula}",
                formula=structure.chemical_formula,
                struct_iri=structure.instance_iri,
            ):
                result = await _run_mlff_work_in_assigned_slot(
                    state,
                    structure,
                    _worker_without_gpu_slot(run_elasticity),
                )
                values = {
                    k: result.get(k)
                    for k in (
                        "bulk_modulus_vrh",
                        "shear_modulus_vrh",
                        "youngs_modulus",
                    )
                }
                state.add_summary(
                    f"Elasticity done for {structure.chemical_formula}. {values}"
                )

                return PropertyResultCarrier(
                    structure_iri=structure.instance_iri,
                    structure_chemical_formula=structure.chemical_formula,
